1	// Unit tests for hybrid/program_buffer.hpp.
2	// Pure compile-time and recording-bus tests -- no SystemC, no hardware.
3	
4	#include "hybrid/program_buffer.hpp"
5	
6	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
