160	        CHECK(bus.writes[i].val == (0xAA000000u | i));
161	    }
162	    CHECK(bus.writes[15].reg == kProgbuf0 + 15u);
163	    CHECK(bus.writes[15].val == kEbreak);
164	    CHECK(bus.writes[16].reg == 0x17u);
165	    CHECK(bus.writes[16].val == kExecProgbufCmd);
166	}
167	
168	TEST_CASE("exec_progbuf: 16 instructions throws - no bus writes happen")
169	{
170	    RecBus bus;
171	    std::array<uint32_t, 16> insns{};
172	    CHECK_THROWS_AS(exec_progbuf(bus, insns), std::runtime_error);
173	    CHECK(bus.writes.empty());
174	}
175	
176	TEST_CASE("exec_progbuf: clears sticky cmderr before issuing exec command")
177	{
178	    RecBus bus;
179	    // abstractcs returns cmderr=set on the first read (pre-exec check),
180	    // then 0 thereafter (poll + final check)
181	    constexpr uint32_t kCmderrMask = 0x7u << 8;
182	    bus.read_seq[0x16u] = {kCmderrMask, 0u, 0u};
183	
184	    const std::array<uint32_t, 1> insns{0x1u};
185	    exec_progbuf(bus, insns);
186	
187	    // Expected writes: progbuf0=insn, progbuf1=ebreak,
188	    //                  abstractcs=kCmderrMask (W1C clear),
189	    //                  command=kExecProgbufCmd
190	    REQUIRE(bus.writes.size() == 4u);
191	    CHECK(bus.writes[2].reg == 0x16u);
192	    CHECK(bus.writes[2].val == kCmderrMask);
193	    CHECK(bus.writes[3].reg == 0x17u);
194	    CHECK(bus.writes[3].val == kExecProgbufCmd);
195	}
196	
197	TEST_CASE("exec_progbuf: throws when cmderr set after execution")
198	{
199	    RecBus bus;
200	    constexpr uint32_t kCmderrMask = 0x7u << 8;
201	    // reads: [pre-exec cmderr check=0], [busy poll=0], [final cmderr check=set]
202	    bus.read_seq[0x16u] = {0u, 0u, kCmderrMask};
203	
204	    const std::array<uint32_t, 1> insns{0x1u};
205	    CHECK_THROWS_AS(exec_progbuf(bus, insns), std::runtime_error);
206	}
207	
208	TEST_CASE("exec_progbuf: polls while busy before returning")
209	{
210	    RecBus bus;
211	    constexpr uint32_t kBusy = 1u << 12;
212	    // abstractcs: no pre-cmderr, busy once, then clear, then no post-cmderr
213	    bus.read_seq[0x16u] = {0u, kBusy, 0u, 0u};
214	
215	    const std::array<uint32_t, 1> insns{0x1u};
216	    CHECK_NOTHROW(exec_progbuf(bus, insns));
217	}
218	
219	// ---- pb_v_data_sweep batching tests ----------------------------------------
220	// Each Program-Buffer execution is one halted-hart DM round-trip (~1000 sim
221	// cycles in the busy-poll), so the cost is the NUMBER of executions, not the
222	// bytes moved. The sweep batches (transfer; addi) pairs into each execution
223	// and advances the base pointer x7 with the in-buffer addi, so 32 registers
224	// cost ceil(32/7)=5 executions and ONE x7 abstract write -- instead of 32
225	// executions plus 32 per-register x7 writes.
226	
227	namespace {
228	constexpr uint8_t kCommandReg = 0x17u;
229	
230	int count_exec_cmds(const RecBus& bus)
231	{
232	    int n = 0;
233	    for (const auto& w : bus.writes)
234	        if (w.reg == kCommandReg && w.val == kExecProgbufCmd) ++n;
235	    return n;
236	}
237	
238	int count_x7_abstract_writes(const RecBus& bus)
239	{
240	    int n = 0;
241	    for (const auto& w : bus.writes)
242	        if (w.reg == kCommandReg && (w.val & 0xFFFFu) == regno_gpr(7)
243	            && ((w.val >> 16) & 1u) != 0u)
244	            ++n;
245	    return n;
246	}
247	
248	bool progbuf_holds(const RecBus& bus, uint32_t insn)
249	{
250	    for (const auto& w : bus.writes)
251	        if (w.reg >= kProgbuf0 && w.reg <= kProgbuf0 + kProgbufMaxInsns
252	            && w.val == insn)
253	            return true;
254	    return false;
255	}
256	}  // namespace
257	
258	TEST_CASE("pb_v_data_sweep: batches transfers into few PB executions, "
259	          "staging the scratch base pointer once")
260	{
261	    RecBus bus;
262	    constexpr uint64_t kScratch = 0x90000000ull;
263	    constexpr uint64_t kStride  = 128;  // HYBRID_VLEN_BYTES_MAX wire span
264	
265	    pb_v_data_sweep(bus, kScratch, kStride, /*vlenb=*/64, /*load=*/true);
266	
267	    // 1 vsetvl execution + ceil(32/7)=5 batch executions = 6 (was 1 + 32 = 33).
268	    CHECK(count_exec_cmds(bus) == 6);
269	    // The base pointer is staged once; the in-buffer addi advances it.
270	    CHECK(count_x7_abstract_writes(bus) == 1);
271	    CHECK(progbuf_holds(bus, encode_addi(7, 7, int32_t(kStride))));
272	
273	    // The single x7 abstract write stages the scratch BASE (data0/data1 are the
274	    // two writes immediately preceding the command).
275	    bool first_x7_is_base = false;
276	    for (std::size_t i = 2; i < bus.writes.size(); ++i) {
277	        const auto& w = bus.writes[i];
278	        if (w.reg == kCommandReg && (w.val & 0xFFFFu) == regno_gpr(7)
279	            && ((w.val >> 16) & 1u) != 0u) {
280	            first_x7_is_base =
281	                bus.writes[i - 2].reg == kDmiData0
282	                && bus.writes[i - 2].val == uint32_t(kScratch & 0xFFFFFFFFu)
283	                && bus.writes[i - 1].reg == kDmiData1
284	                && bus.writes[i - 1].val == uint32_t(kScratch >> 32);
285	            break;
286	        }
287	    }
288	    CHECK(first_x7_is_base);
289	
290	    // All 32 vle8.v are present across the progbuf slots (not just progbuf0).
291	    int found = 0;
292	    for (uint16_t v = 0; v < 32; ++v)
293	        if (progbuf_holds(bus, encode_vle8_v(uint8_t(v), 7))) ++found;
294	    CHECK(found == 32);
295	}
296	
297	TEST_CASE("pb_v_data_sweep: load=false emits a vse8.v for every register")
298	{
299	    RecBus bus;
300	    pb_v_data_sweep(bus, 0x90000000ull, 128, /*vlenb=*/64, /*load=*/false);
301	
302	    int found = 0;
303	    for (uint16_t v = 0; v < 32; ++v)
304	        if (progbuf_holds(bus, encode_vse8_v(uint8_t(v), 7))) ++found;
305	    CHECK(found == 32);
306	    CHECK(count_exec_cmds(bus) == 6);
307	}
