1	// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
2	// ops against the RISC-V Debug Module. The orchestration is testable in
3	// isolation by injecting a recording bus.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/andes_caps.hpp"
7	#include "hybrid/program_buffer.hpp"
8	#include "hybrid/resume_driver.hpp"
9	#include "hybrid/state_abi.h"
10	#include "hybrid/v_regfile_xfer.hpp"
11	
12	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
13	#include <doctest.h>
14	
15	#include <cstdint>
16	#include <deque>
17	#include <optional>
18	#include <set>
19	#include <unordered_map>
20	#include <vector>
21	
22	namespace {
23	
24	// DMI register addresses from RISC-V Debug Spec 1.0.
25	constexpr uint8_t kDmcontrol  = 0x10;
26	constexpr uint8_t kDmstatus   = 0x11;
27	constexpr uint8_t kAbstractcs = 0x16;
28	constexpr uint8_t kCommand    = 0x17;
29	constexpr uint8_t kData0      = 0x04;
30	constexpr uint8_t kData1      = 0x05;
31	
32	// CSR numbers from Debug Spec.
33	constexpr uint16_t kCsrDpc  = 0x7B1;
34	constexpr uint16_t kCsrDcsr = 0x7B0;
35	
36	// L26: the V scratch GPA is a runtime value (mmap top page) passed to the
37	// driver. Tests pass this distinctive stand-in and assert the sweep uses it.
38	constexpr uint64_t kScratch = 0x07FFF000ull;  // 128 MiB mmap top page
39	
40	struct DmiOp
41	{
42	  enum class Kind
43	  {
44	    Write,
45	    Read,
46	  };
47	  Kind kind;
48	  uint8_t reg;
49	  uint32_t value;  // for writes only
50	};
51	
52	struct RecordingBus final : hybrid::DmiBus
53	{
54	  std::vector<DmiOp> ops;
55	
56	  // Test-controlled response values for reads.
57	  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
58	  uint32_t abstractcs_value = 0;     // fallback when queue is empty
59	  std::deque<uint32_t> abstractcs_queue; // queued reads drain first
60	
61	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
62	  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
63	  // fallback). Models real hardware and -- unlike positional queueing -- is
64	  // robust to however many unrelated abstract ops precede the targeted write.
65	  std::optional<uint16_t> fail_csr_write;
66	
67	  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
68	  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
69	  // re-arms to false after firing - tests can flip it back on to fail a
70	  // later PB exec.
71	  bool fail_next_pb_exec = false;
72	
73	  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
74	  // into regfile[regno]; abstract read-COMMANDs load it back so read-modify-
75	  // write-verify sequences observe their own writes. Regnos in warl_ignore
76	  // model WARL fields the hart pins (the write is recorded but discarded),
77	  // e.g. dcsr.prv on a core without S/U modes.
78	  std::unordered_map<uint16_t, uint64_t> regfile;
79	  std::set<uint16_t> warl_ignore;
80	
81	  void write(uint8_t reg, uint32_t value) override
